import React, { useState, useEffect } from "react";
import axios from "axios";
import "./ViewTasks.css"; 
import Navbar from "../components/navbar"; 
import Footer from "../components/footer"; 
import StudentSidebar from "../components/StudentSidebar"; 

const ViewTasks = () => {
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [newMilestone, setNewMilestone] = useState({
    title: "",
    dueDate: "",
    status: "Pending"
  });
  const [newTask, setNewTask] = useState({
    title: "",
    status: "Pending",
    uploadedBy: ""
  });
  const [currentUser, setCurrentUser] = useState(null);
  const [studentInfo, setStudentInfo] = useState(null);
  const [groupInfo, setGroupInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch user data on component mount
  useEffect(() => {
    const user = JSON.parse(localStorage.getItem('user'));
    if (!user) {
      window.location.href = '/login';
      return;
    }
    setCurrentUser(user);

    // Fetch student information
    const fetchStudentInfo = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/api/student/user/${user._id}`);
        setStudentInfo(response.data);

        // Check if student is grouped
        if (response.data.isGrouped) {
          const groupResponse = await axios.get(`http://localhost:5000/api/group/student/${response.data.regNo}`);
          setGroupInfo(groupResponse.data);

          // Fetch milestones for the project
          const milestonesResponse = await axios.get(`http://localhost:5000/api/milestone/project/${groupResponse.data.projectID}`);
          setMilestones(milestonesResponse.data);

          // Fetch tasks for all milestones
          const tasksPromises = milestonesResponse.data.map(milestone => 
            axios.get(`http://localhost:5000/api/task/milestone/${milestone._id}`)
          );
          const tasksResponses = await Promise.all(tasksPromises);
          const allTasks = tasksResponses.flatMap(response => response.data);
          setTasks(allTasks);
        }
      } catch (err) {
        setError(err.response?.data?.message || "Error fetching data");
      } finally {
        setLoading(false);
      }
    };

    fetchStudentInfo();
  }, []);

  // Function to add a new milestone
  const handleAddMilestone = async () => {
    if (!newMilestone.title.trim() || !newMilestone.dueDate) {
      alert("Please fill in all milestone fields.");
      return;
    }

    if (!groupInfo) {
      alert("You must be in a group to add milestones.");
      return;
    }

    try {
      const milestoneData = {
        ...newMilestone,
        projectID: groupInfo.projectID
      };

      const response = await axios.post("http://localhost:5000/api/milestone", milestoneData);
      setMilestones([...milestones, response.data]);
      setNewMilestone({ title: "", dueDate: "", status: "Pending" });
    } catch (err) {
      setError(err.response?.data?.message || "Error adding milestone");
    }
  };

  // Function to add a new task under a specific milestone
  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      alert("Please fill in the task title.");
      return;
    }

    if (!studentInfo) {
      alert("Student information not available.");
      return;
    }

    try {
      const taskData = {
        ...newTask,
        milestoneId,
        uploadedBy: studentInfo.studentName
      };

      const response = await axios.post("http://localhost:5000/api/task", taskData);

      // Update tasks state
      setTasks([...tasks, response.data]);

      // Reset task fields
      setNewTask({ title: "", status: "Pending", uploadedBy: "" });
    } catch (err) {
      setError(err.response?.data?.message || "Error adding task");
    }
  };

  // Function to update task status
  const handleUpdateTaskStatus = async (taskId, newStatus) => {
    if (!studentInfo) {
      alert("Student information not available.");
      return;
    }

    try {
      const updatedTask = {
        status: newStatus,
        uploadedBy: studentInfo.studentName
      };

      await axios.put(`http://localhost:5000/api/task/${taskId}`, updatedTask);

      // Update the task in state
      setTasks(tasks.map(task => 
        task._id === taskId 
          ? { ...task, status: newStatus, uploadedBy: studentInfo.studentName }
          : task
      ));
    } catch (err) {
      setError(err.response?.data?.message || "Error updating task");
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  if (!studentInfo?.isGrouped) {
    return (
      <div className="tasks-container">
        <Navbar />
        <div className="content-wrapper">
          <StudentSidebar />
          <div className="main-content">
            <h1 className="tasks-title">Manage Milestones and Tasks</h1>
            <div className="not-grouped-message">
              <p>You are not currently in a group. Please join or create a group to view and manage tasks.</p>
            </div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>
          <p>Project: {groupInfo?.projectID}</p>

          {/* Input Field for Adding a Milestone */}
          <div className="milestone-section">
            <input 
              type="text" 
              value={newMilestone.title} 
              onChange={(e) => setNewMilestone({...newMilestone, title: e.target.value})} 
              placeholder="Milestone title" 
            />
            <input
              type="date"
              value={newMilestone.dueDate}
              onChange={(e) => setNewMilestone({...newMilestone, dueDate: e.target.value})}
            />
            <button onClick={handleAddMilestone}>Add Milestone</button>
          </div>

          {/* List of Milestones with Tasks */}
          <div className="milestone-list">
            {milestones.map((milestone) => (
              <div key={milestone._id} className="milestone-item">
                <h2>{milestone.title}</h2>
                <p>Due Date: {new Date(milestone.dueDate).toLocaleDateString()}</p>
                <p>Status: {milestone.status}</p>

                {/* Input Fields for Adding a Task to the Milestone */}
                <div className="task-section">
                  <input 
                    type="text" 
                    value={newTask.title} 
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })} 
                    placeholder="Task title" 
                  />
                  <button 
                    className="task-button" 
                    onClick={() => handleAddTask(milestone._id)}
                  >
                    Add Task
                  </button>

                  {/* Table of Tasks Under the Milestone */}
                  <div className="tasks-table">
                    <table>
                      <thead>
                        <tr>
                          <th>Task</th>
                          <th>Uploaded By</th>
                          <th>Status</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {tasks
                          .filter(task => task.milestoneId === milestone._id)
                          .map((task) => (
                            <tr key={task._id}>
                              <td>{task.title}</td>
                              <td>{task.uploadedBy}</td>
                              <td>{task.status}</td>
                              <td>
                                {task.status !== "Completed" && (
                                  <button 
                                    className="mark-completed-button" 
                                    onClick={() => handleUpdateTaskStatus(task._id, "Completed")}
                                  >
                                    Mark as Completed
                                  </button>
                                )}
                              </td>
                            </tr>
                          ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
